**2. 게임 캐릭터 시스템 (Entity Component System)**

전통적 방식:
```python
class Player:
    def __init__(self):
        self.x, self.y = 0, 0
        self.health = 100
        self.speed = 5

    def move(self, dx, dy):
        self.x += dx * self.speed
        self.y += dy * self.speed
```

DOP/ECS 방식:
```python
# 게임 상태를 단순한 데이터로 표현
game_state = {
    'entities': [
        {
            'id': 'player1',
            'components': {
                'position': {'x': 0, 'y': 0},
                'health': {'current': 100, 'max': 100},
                'movement': {'speed': 5}
            }
        },
        {
            'id': 'enemy1',
            'components': {
                'position': {'x': 50, 'y': 30},
                'health': {'current': 80, 'max': 80},
                'ai': {'type': 'aggressive'}
            }
        }
    ]
}

# 시스템들이 데이터를 변환
def movement_system(game_state, input_commands):
    new_entities = []
    for entity in game_state['entities']:
        if 'movement' in entity['components'] and entity['id'] in input_commands:
            cmd = input_commands[entity['id']]
            pos = entity['components']['position']
            speed = entity['components']['movement']['speed']

            new_pos = {
                'x': pos['x'] + cmd['dx'] * speed,
                'y': pos['y'] + cmd['dy'] * speed
            }

            new_entity = {
                **entity,
                'components': {
                    **entity['components'],
                    'position': new_pos
                }
            }
            new_entities.append(new_entity)
        else:
            new_entities.append(entity)

    return {**game_state, 'entities': new_entities}
```

