# DOP 스타일 데이터 변환
def filter_purchases(actions):
    return [action for action in actions if action['action'] == 'purchase']

def calculate_daily_revenue(purchase_actions):
    from collections import defaultdict
    daily_revenue = defaultdict(int)

    for action in purchase_actions:
        date = action['timestamp'][:10]  # YYYY-MM-DD
        daily_revenue[date] += action['amount']

    return dict(daily_revenue)

